SELECT $j$sa-dec-flower-half-marathon-2026-nhan-dien-race-kit$j$, 'article', 'tin-tuc', $j$Sa Đéc Flower Half Marathon 2026 ra mắt bộ nhận diện và race kit: áo, túi, BIB, huy chương mang sắc hoa hồng$j$,
  $j$Ban tổ chức Sa Đéc Flower Half Marathon 2026 chính thức công bố bộ nhận diện lấy cảm hứng từ hoa hồng Sa Đéc cùng race kit gồm áo runner, áo finisher 21 km, túi rút, BIB và bộ huy chương ba cự ly.$j$,
  $j$[{"type": "p", "text": "Ban tổ chức **Sa Đéc Flower Half Marathon 2026** (25–27/12/2026, Làng hoa Sa Đéc – phường Sa Đéc, Đồng Tháp) vừa chính thức ra mắt **bộ nhận diện** và **race kit** của mùa giải đầu tiên. Lấy cảm hứng từ vẻ đẹp của Làng hoa Sa Đéc – thủ phủ hoa kiểng miền Tây, toàn bộ thiết kế mang diện mạo trẻ trung, tươi mới, đậm dấu ấn vùng đất Đồng Tháp."}, {"type": "h2", "text": "🌹 Logo – hoa hồng và runner trong chữ S"}, {"type": "image", "file": "https://www.caycanhmientay.com/images/su-kien/sadec-marathon-2026-logo.jpg", "caption": "Logo Sa Đéc Flower Half Marathon 2026 và các phiên bản trên nền màu (ảnh: Ban tổ chức)"}, {"type": "p", "text": "Logo là chữ **S** uốn lượn như dải lụa đỏ cam – gợi dòng sông và cung đường chạy – nối với chữ **Đ** có hình **runner đang sải bước**, trên cùng là **đóa hồng** đang nở. Hoa hồng là biểu tượng của vẻ đẹp, sự tươi mới và nguồn năng lượng tích cực, cũng là loài hoa gắn bó với nhà vườn Sa Đéc qua nhiều thế hệ. Logo có phiên bản màu trên nền trắng và phiên bản trắng trên nền gradient xanh lá hoặc cam đỏ."}, {"type": "h2", "text": "🎨 Bảng màu – từ xanh lá vườn đến đỏ hoa hồng"}, {"type": "image", "file": "https://www.caycanhmientay.com/images/su-kien/sadec-marathon-2026-palette.jpg", "caption": "Bảng màu chính thức của giải (ảnh: Ban tổ chức)"}, {"type": "table", "rows": [["Màu", "Mã HEX", "Gợi hình ảnh"], ["Xanh lá đậm", "#006838", "Lá cây, vườn kiểng"], ["Xanh chanh", "#D7DF23", "Chồi non, sức sống"], ["Đỏ", "#ED1C24", "Hoa hồng Sa Đéc"], ["Cam", "#F7941D", "Nắng miền Tây, năng lượng"]]}, {"type": "p", "text": "Bốn màu được phối thành hai dải chuyển: **xanh lá đậm → xanh chanh** và **đỏ → cam**, xuất hiện xuyên suốt trên áo, BIB, dây huy chương và ấn phẩm."}, {"type": "h2", "text": "🌸 Mascot – bông hồng runner"}, {"type": "image", "file": "https://www.caycanhmientay.com/images/su-kien/sadec-marathon-2026-mascot.jpg", "caption": "Mascot bông hồng đeo băng đô thể thao, mang giày chạy (ảnh: Ban tổ chức)"}, {"type": "p", "text": "Linh vật của giải là một **nụ hồng đỏ cam** bọc trong đài lá xanh, gương mặt hình trái tim, đeo **băng đô thể thao** và mang **giày chạy** – vui tươi, quyết tâm, sẵn sàng xuất phát."}, {"type": "h2", "text": "🎽 Áo runner – \"Run for a Brighter Sa Đéc\""}, {"type": "image", "file": "https://www.caycanhmientay.com/images/su-kien/sadec-marathon-2026-ao-runner.jpg", "caption": "Áo runner mặt trước và mặt sau (ảnh: Ban tổ chức)"}, {"type": "p", "text": "Áo chạy sự kiện kiểu raglan, thân trắng, tay áo chuyển **cam – đỏ**, phần dưới là những **cánh hoa** nhiều màu xếp lớp trên nền xanh lá. Mặt sau in dòng chữ viết tay **\"Run for a Brighter Sa Đéc\"**, tay áo in slogan **Chinh phục cung đường hoa**."}, {"type": "h2", "text": "🏆 Áo finisher 21 km"}, {"type": "image", "file": "https://www.caycanhmientay.com/images/su-kien/sadec-marathon-2026-ao-finisher.jpg", "caption": "Áo Finisher 21 km Half Marathon (ảnh: Ban tổ chức)"}, {"type": "p", "text": "Dành cho runner hoàn thành cự ly bán marathon: áo **xanh lá – vàng chanh**, chữ **FINISHER 21 KM HALF MARATHON** chạy dọc thân, phần dưới in hình **những luống hoa trên giàn** đặc trưng của làng hoa Sa Đéc."}, {"type": "h2", "text": "👜 Túi race kit"}, {"type": "image", "file": "https://www.caycanhmientay.com/images/su-kien/sadec-marathon-2026-tui-race-kit.jpg", "caption": "Túi rút đựng race kit (ảnh: Ban tổ chức)"}, {"type": "p", "text": "Túi rút dây tiện dụng, in logo, thời gian – địa điểm và hình hai runner chạy qua **cổng Làng hoa Sa Đéc** giữa hai hàng hoa rực rỡ."}, {"type": "h2", "text": "🔢 BIB chạy bộ theo màu cự ly"}, {"type": "image", "file": "https://www.caycanhmientay.com/images/su-kien/sadec-marathon-2026-bib.jpg", "caption": "Mẫu BIB 5 km, 10 km, 21 km (ảnh: Ban tổ chức)"}, {"type": "p", "text": "Mỗi cự ly có màu riêng để dễ nhận diện trên đường chạy: **5 km xanh dương**, **10 km đỏ cam**, **21 km xanh lá**."}, {"type": "h2", "text": "🏅 Huy chương hoàn thành"}, {"type": "image", "file": "https://www.caycanhmientay.com/images/su-kien/sadec-marathon-2026-huy-chuong.jpg", "caption": "Huy chương và dây đeo ba cự ly (ảnh: Ban tổ chức)"}, {"type": "p", "text": "Huy chương màu đồng vàng, viền lá, nổi bật logo hoa hồng, **cổng làng hoa** và **cung đường uốn lượn giữa hai hàng hoa**, khắc dòng chữ **Chinh phục cung đường hoa**. Dây đeo cùng màu với BIB của từng cự ly. Đây là huy chương của **mùa giải đầu tiên** – kỷ niệm không lặp lại cho mỗi runner về đích."}, {"type": "h2", "text": "📣 Ấn phẩm truyền thông (POSM)"}, {"type": "image", "file": "https://www.caycanhmientay.com/images/su-kien/sadec-marathon-2026-posm.jpg", "caption": "Băng rôn và standee của giải (ảnh: Ban tổ chức)"}, {"type": "p", "text": "Băng rôn, standee sẽ xuất hiện khắp phường Sa Đéc trong những ngày diễn ra giải, đồng hành cùng UBND phường Sa Đéc."}, {"type": "h2", "text": "Hơn cả một giải chạy"}, {"type": "p", "text": "Hãy tưởng tượng bạn sải bước giữa làng hoa đang vào vụ Tết, cảm nhận nhịp sống bình dị miền Tây và cùng hàng nghìn runner viết nên những khoảnh khắc đáng nhớ. Dù là runner dày dạn hay người mới bắt đầu, đây là dịp để thử thách bản thân và kết nối cộng đồng. Xem thêm [sơ đồ đường chạy cập nhật 5 km, 10 km, 21 km](/tin-tuc/sa-dec-flower-half-marathon-2026-cap-nhat-duong-chay)."}, {"type": "note", "title": "Thông tin giải chạy", "text": "📅 25 – 27/12/2026 · 📍 Làng hoa Sa Đéc – P. Sa Đéc, tỉnh Đồng Tháp · Đăng ký: sadecmarathon.com · ☎️ Hotline: 088 869 69 70."}, {"type": "p", "text": "Chạy xong, mời bạn ghé vườn **Cây Cảnh Miền Tây** ngay giữa làng hoa để tham quan và chọn cây hoa Tết – xem [hệ thống cửa hàng](/he-thong-cua-hang). Hẹn gặp bạn trên cung đường hoa tháng 12 này! 🌹"}]$j$::jsonb,
